(function(){'use strict';const M=Motion,F=M.sceneFX,types=['focus-halo','distraction-pings','thought-cloud','overwhelm-scribble','task-complete','progress-rise','energy-charge','energy-drain','habit-chain','time-pressure','motivation-rays','calm-breath'];F.effects.push(...types);const before=F.object;F.object=function(c,o,t,phase){before(c,o,t,phase);if(phase!=='front')return;const time=o._localTime??t,r=Math.max(o.w,o.h)*.6,s=o.effectSize||1,col=o.effectColor||'#e0bc75';c.save();c.globalAlpha*=o.effectStrength??.8;c.strokeStyle=col;c.lineWidth=3*s;for(const k of o.effects||[]){if(!types.includes(k))continue;const y=-o.h*.6;if(['focus-halo','calm-breath'].includes(k)){const pulse=1+.15*Math.sin(time*2);c.beginPath();c.ellipse(0,0,(o.w*.7+15)*s*pulse,(o.h*.6+15)*s*pulse,0,0,Math.PI*2);c.stroke()}else if(k==='task-complete'){const p=Math.min(1,(time%2)*2);M.line(c,[[-22,y],[0,y+20],[40*p,y+20-55*p]],col,7*s)}else if(k==='progress-rise'){for(let i=0;i<3;i++){const yy=y-(time*40+i*25)%100;M.line(c,[[-12,yy+12],[0,yy],[12,yy+12]],col,4*s)}}else if(k==='energy-charge'||k==='energy-drain'){M.rr(c,-35,y-40,70,30,4,'#e9eee4');const p=(time*.4)%1;M.rr(c,-30,y-35,60*(k==='energy-charge'?p:1-p),20,2,col)}else if(k==='overwhelm-scribble'){c.beginPath();for(let i=0;i<80;i++){const a=i*.6+time;const x=Math.cos(a)*r*.5,yy=y+Math.sin(i*1.7+time*4)*24;i?c.lineTo(x,yy):c.moveTo(x,yy)}c.stroke()}else if(k==='thought-cloud'){for(let i=0;i<5;i++)M.ellipse(c,(i-2)*20,y-25+Math.sin(i+time)*5,24,18,'#e3e9e5');M.ellipse(c,15,y+12,8,8,'#e3e9e5')}else if(k==='time-pressure'){c.beginPath();c.arc(0,y-15,28,0,Math.PI*2);c.stroke();M.line(c,[[0,y-15],[Math.sin(time*5)*21,y-15-Math.cos(time*5)*21]],col,4)}else for(let i=0;i<8;i++){const a=i*Math.PI/4+time*.2,x=Math.cos(a)*r*s,yy=Math.sin(a)*r*s;if(k==='motivation-rays')M.line(c,[[x,yy],[x*1.2,yy*1.2]],col,4*s);if(k==='habit-chain'){c.beginPath();c.ellipse(x,yy,13*s,7*s,a,0,Math.PI*2);c.stroke()}if(k==='distraction-pings'){M.rr(c,x-14,yy-10,28,20,4,col);c.fillStyle='#fff';c.font='bold 16px Arial';c.textAlign='center';c.fillText('!',x,yy+6)}}}c.restore()};M.productivityEffects=types})();
